// ===== BANK EXPANSION 2 — authored length-matched =====
// ans: [type, display text (65–105 chars), why].  m: full model (book) answer shown in reveal / examiner console.
const BANK2 = [
// ---------- AREA I ----------
{id:"I-A-6",a:"I",t:"A",d:2,ref:"AIH ch. 2 — Domains of learning",
 q:"What are the domains of learning, and which one matters most when teaching a hot inflation?",
 m:"Cognitive (knowledge), affective (attitudes, beliefs, values), and psychomotor (physical skills). Hot inflation is primarily psychomotor, but the affective domain — a safety attitude toward crew and fabric — and the cognitive domain (why short, centered burns) are both in play.",
 ans:[["B","Cognitive, affective, psychomotor — inflation is mostly psychomotor, plus attitude.","AIH's three domains, correctly applied."],
 ["S","Knowledge, attitude, and hands-on skill — for inflation it's mostly the hands-on part.","Correct domains in plain language without the terms."],
 ["W","Rote, understanding, application, correlation — inflation lives at the application level.","Those are levels of learning, not domains."],
 ["W","Visual, auditory, and kinesthetic domains — inflation is kinesthetic, so just let them feel it.","Learning-styles labels aren't the AIH domains of learning."]]},

{id:"I-A-7",a:"I",t:"A",d:2,ref:"AIH ch. 2 — Learning plateaus",
 q:"Your student's landings were improving, then stalled for three flights. What's going on and what do you do?",
 m:"A learning plateau — a normal, temporary leveling-off in skill progress. Tell the student it's normal, vary the practice or switch to related tasks, keep motivation up, and avoid over-drilling the same thing. Rule out other causes (fatigue, stress, unclear standard).",
 ans:[["B","A learning plateau — normal and temporary; explain it, vary practice, and keep them motivated.","Correct identification and response."],
 ["S","They've hit a wall that happens to everyone — I'd mix up the lessons so they don't get frustrated.","Right idea without the term."],
 ["W","It means they've reached their natural ceiling for balloon skill, so I'd slow the syllabus way down.","Plateaus are temporary, not a fixed ability ceiling."],
 ["W","Lack of effort — I'd schedule extra landings back-to-back until they break through it.","Over-drilling often prolongs a plateau."]]},

{id:"I-C-2",a:"I",t:"C",d:2,ref:"AIH ch. 4 — Preparation and presentation",
 q:"You have a ground lesson tonight on propane safety. How do you prepare and what presentation method fits?",
 m:"Preparation: review the objective, the learner's background, references, a lesson plan, and aids (a cylinder, valves, photos). Presentation: lecture with guided discussion fits knowledge content; then have the learner apply it (walk-through of a real cylinder), followed by review and evaluation.",
 ans:[["B","Objective, references, a plan, and aids; lecture and discussion, then a hands-on review.","Matches the teaching process with an appropriate method."],
 ["S","I'd read up, plan what to cover, bring an actual cylinder, talk through it, then quiz them.","All four steps informally."],
 ["W","No prep needed for a ground lesson — I know propane well enough to just talk through it.","Preparation is the first step of the teaching process."],
 ["W","Demonstration-performance is the only valid method for safety topics, so we'd go fill tanks.","Knowledge content suits lecture/discussion; the method should match the material."]]},

{id:"I-D-3",a:"I",t:"D",d:2,ref:"AIH ch. 4 — Guided discussion; question types",
 q:"In a guided discussion, what types of questions can you use?",
 m:"Overhead (to the whole group), rhetorical (answered by the instructor), direct (to one person), reverse (student's question returned to them), and relay (student's question redirected to the group). Questions should be open-ended to draw on the learners' existing knowledge.",
 ans:[["B","Overhead, rhetorical, direct, reverse, and relay — open-ended to draw out what they know.","AIH question types."],
 ["S","Questions to the whole group, to one person, and bouncing a question back to the student or the group.","Describes the types without the names."],
 ["W","Mostly yes-or-no questions, so the discussion stays focused and moves along quickly.","Guided discussion relies on open-ended questions."],
 ["W","Trick and puzzle questions — they keep the group alert and show who really knows it.","AIH lists those as question types to avoid."]]},

{id:"I-E-4",a:"I",t:"E",d:2,ref:"AIH ch. 5 — Responses to learner questions",
 q:"Your student asks something about the regulations that you honestly don't know. What do you do?",
 m:"Admit you don't know, commit to finding the answer, look it up with the learner when practical (modeling research skills with the CFR/AIM/handbook), and follow up. Never bluff — a wrong answer erodes credibility and can teach an error.",
 ans:[["B","Admit I don't know, find the answer — with them if possible — and follow up.","AIH guidance."],
 ["S","Tell them I'm not sure and that I'll get back to them with the right answer next time.","Correct core; misses looking it up together."],
 ["W","Give my best guess confidently, so the student keeps trust in me as the instructor.","Bluffing damages credibility and teaches errors."],
 ["W","Tell them it won't be on the checkride, so it isn't worth spending lesson time on.","Dismissive and may be wrong; responding to questions is an instructor duty."]]},

{id:"I-E-5",a:"I",t:"E",d:2,ref:"PTS — Unsatisfactory Performance, Letter of Discontinuance; 14 CFR 61.43",
 q:"If you fail a Task today, what happens — and what's a letter of discontinuance?",
 m:"Failing any Task fails that Area and the practical test; I'd receive an 8060-5 Notice of Disapproval listing the failed Area(s)/Task(s) and Areas not tested, and I can choose to continue for credit. Under 61.43, credit for Areas passed is kept if I retest within 60 days. A letter of discontinuance is issued when the test stops for reasons other than performance — weather, equipment, illness — and lists the Areas completed.",
 ans:[["B","An 8060-5; passed Areas carry over within 60 days. Discontinuance is for non-performance.","Accurate under the PTS and 61.43."],
 ["S","I'd get a pink slip for the failed part and could redo just that part later if it's soon enough.","Correct gist; missing the specifics."],
 ["W","A failed Task can be retaught and retried on the spot; the DPE then grades the second attempt.","Instruction/practice isn't permitted during the test."],
 ["W","A letter of discontinuance means the test was failed but the DPE chose a gentler form.","Discontinuance is for non-performance reasons only."]]},

{id:"I-F-6",a:"I",t:"F",d:2,c:1,ref:"PTS — Positive Exchange of Flight Controls; AIH",
 q:"How do you and a student transfer control of the balloon?",
 m:"Brief it before flight and use the three-step positive exchange: 'You have the flight controls.' — 'I have the flight controls.' — 'You have the flight controls.' Confirm visually. There's never doubt who is flying; in a balloon that includes who is operating the burner and the vent line.",
 ans:[["B","A briefed three-step verbal exchange — “You have…” “I have…” “You have…” — then confirm.","PTS-recommended procedure."],
 ["S","We say out loud who has it and confirm it, so there's never confusion over who's on the burner.","Right idea, missing the three-step format."],
 ["W","I just take the blast valve when I need to — in a balloon it's obvious who's flying.","Ambiguity about control is a known accident cause."],
 ["W","A tap on the shoulder means I've taken over; talking in the basket distracts the student.","PTS calls for verbal three-step exchange."]]},

{id:"I-F-7",a:"I",t:"F",d:3,s:1,ref:"AIH ch. 7; 14 CFR 61.39",
 q:"A ride company owner wants you to sign off his new pilot for the commercial checkride by Friday. You don't think the pilot is ready. What do you do?",
 m:"Decline. My endorsement certifies the applicant is prepared (61.39); signing off someone I don't believe is ready is unethical and unsafe and undermines my credibility. Explain the specific deficiencies, offer a training plan, and set an honest timeline. Commercial pressure doesn't change the standard.",
 ans:[["B","Decline — my endorsement certifies readiness. Show the gaps, offer a plan, set an honest date.","Ethical and regulatory answer."],
 ["S","I wouldn't sign it yet — I'd tell the owner what still needs work and how long it'll take.","Correct decision, missing the 61.39 basis."],
 ["W","Sign it — the DPE is the real gate, so if he isn't ready the checkride will catch it.","Shifts responsibility; the endorsement is a certification."],
 ["W","Sign it with a written note in the logbook listing the weak areas for the examiner to probe.","A conditional endorsement still certifies readiness you don't believe in."]]},

{id:"I-G-3",a:"I",t:"G",d:3,ref:"AIH ch. 8/9 — Scenario-based training; learner-centered grading",
 q:"How would you grade your student with learner-centered grading?",
 m:"Maneuver/procedure grades: Describe, Explain, Practice, Perform (and Not Observed). Single-pilot resource management grades: Explain, Practice, Manage-Decide. The learner self-assesses first, then the instructor and learner compare. It fits scenario-based training and builds judgment.",
 ans:[["B","Describe, Explain, Practice, Perform for maneuvers; Explain, Practice, Manage-Decide for SRM.","AIH learner-centered grading scales."],
 ["S","The student rates themselves first on how well they can explain and do it, then we compare notes.","Captures the self-assessment idea without the scale."],
 ["W","Letter grades A through F for each maneuver, recorded so the DPE can see the trend.","Not the AIH learner-centered method."],
 ["W","Satisfactory or unsatisfactory only — anything finer just confuses the student.","Learner-centered grading uses graduated levels."]]},

// ---------- AREA II ----------
{id:"II-A-6",a:"II",t:"A",d:2,ref:"PHAK ch. 17 — Dehydration and heatstroke",
 q:"It's a 92°F August evening flight with a full basket. What aeromedical issues are you watching for?",
 m:"Dehydration and heatstroke for pilot, crew, and passengers — burners add radiant heat in the basket. Symptoms: headache, fatigue, dizziness, cramps, impaired judgment. Carry water, hydrate before flight, brief passengers, and watch older passengers. Hot days also mean higher envelope temperatures and lower performance margins.",
 ans:[["B","Dehydration and heatstroke for everyone aboard — burner heat adds to it — so carry water.","Correct identification and mitigation."],
 ["S","People overheating — I'd make sure everyone drinks water and watch for anyone feeling sick.","Correct practice without the conditions named."],
 ["W","Hypothermia from evening cooling at altitude, so passengers should bring a heavy jacket.","Wrong hazard for a 92°F evening."],
 ["W","None for the passengers — heat only affects the envelope's performance, not people aboard.","Ignores real physiological risks."]]},

{id:"II-A-7",a:"II",t:"A",d:2,ref:"PHAK ch. 17 — Carbon monoxide; hypemic hypoxia",
 q:"During a long tethered session in calm air, your crew chief complains of a headache and drowsiness near the basket. Concern?",
 m:"Possible carbon monoxide exposure — burner combustion products can accumulate around a stationary balloon in calm air. CO causes hypemic hypoxia: headache, drowsiness, dizziness, nausea. Move people to fresh air, reduce burner time, ventilate, and seek medical care if symptoms persist.",
 ans:[["B","Possible CO exposure — hypemic hypoxia. Move them to fresh air and cut the burner time.","Correct recognition and response."],
 ["S","Could be fumes from the burner building up in still air — get them away from the basket.","Correct action; doesn't name CO or the hypoxia type."],
 ["W","Probably hyperventilation from the tether excitement — have them breathe into a paper bag.","Misdiagnosis that delays fresh air."],
 ["W","Propane vapor is a stimulant, so drowsiness rules out the burner — it's just a long day.","Factually wrong and ignores a CO hazard."]]},

{id:"II-B-3",a:"II",t:"B",d:2,ref:"AIM 8-1-6; PHAK ch. 17; AC 90-48",
 q:"How does a pilot's physical or mental condition affect vision and scanning?",
 m:"Fatigue, hypoxia, alcohol, medications, stress, and dehydration all degrade visual acuity, scanning discipline, and peripheral detection. Empty-field myopia sets in when there's nothing to focus on. Low-sun glare at sunrise/sunset launches compounds it. Use a disciplined sector scan and stay fit to fly.",
 ans:[["B","Fatigue, hypoxia, alcohol, and stress all degrade vision — so scan deliberately in sectors.","PTS II.B.1 elements."],
 ["S","When you're tired or not feeling well you don't see as well, so you have to scan on purpose.","Correct core without specifics."],
 ["W","Vision is fixed by your medical exam — condition doesn't matter if you passed the eye test.","Condition affects performance regardless of medical results."],
 ["W","Mental condition affects decisions, not eyesight, so scanning technique stays the same.","Stress and fatigue degrade visual search."]]},

{id:"II-C-4",a:"II",t:"C",d:3,ref:"BFH; FAA-H-8083-28 — Temperature inversions",
 q:"You climb out of the morning surface inversion and the balloon suddenly slows its climb. Why?",
 m:"Lift depends on the temperature difference between envelope air and ambient air. Climbing into the warmer inversion layer reduces that difference, so lift drops and the climb slows or stops — the balloon may seem to hit a ceiling. Descending back into the colder surface air increases lift. Anticipate with more heat when climbing into the inversion.",
 ans:[["B","The warmer inversion layer shrinks the temperature difference, so lift drops.","Correct physics and anticipation."],
 ["S","It's warmer up there, so the balloon has less lift and needs more heat to keep climbing.","Correct reasoning in plain language."],
 ["W","The air pressure drops in the inversion, which compresses the envelope and spills hot air.","Not the mechanism."],
 ["W","Inversions push air downward, like a lid, which physically holds the balloon down.","Inversions are temperature structure, not a downward air current."]]},

{id:"II-D-3",a:"II",t:"D",d:2,c:1,ref:"14 CFR 91.119",
 q:"What minimum safe altitudes apply to you over a town and over open farmland?",
 m:"91.119 applies except when necessary for takeoff or landing: always an altitude allowing an emergency landing without undue hazard; over congested areas, 1,000 ft above the highest obstacle within 2,000 ft horizontally; over other than congested areas, 500 ft above the surface (except over open water or sparsely populated areas, where no closer than 500 ft to any person, vessel, vehicle, or structure).",
 ans:[["B","Congested: 1,000 ft above obstacles within 2,000 ft. Otherwise 500 ft, except to land.","Correct 91.119 values with the exception."],
 ["S","1,000 feet over towns and 500 feet over the country, unless I'm taking off or landing.","Correct numbers; misses the 2,000-ft radius."],
 ["W","Balloons are exempt from 91.119 because they're slow and can't steer around populated areas.","No balloon exemption exists."],
 ["W","500 feet everywhere, since balloons don't have engines that could fail over the town.","Congested areas require 1,000 feet."]]},

{id:"II-D-4",a:"II",t:"D",d:2,ref:"14 CFR 91.107(a)(3); 91.103; 91.3",
 q:"Do your passengers need seat belts, and what does 91.103 require of you before every flight?",
 m:"No — 91.107(a)(3) excepts free balloons that incorporate a basket or gondola from the seat/safety belt requirement. 91.103 requires the PIC to become familiar with all available information concerning the flight: weather reports and forecasts, fuel requirements, alternatives if the flight can't be completed as planned, and performance data. 91.3 makes the PIC the final authority.",
 ans:[["B","No — 91.107 excepts basket balloons. 91.103 requires all available info, weather and fuel.","Correct exceptions and requirements."],
 ["S","Balloons don't have seat belts, and I have to know the weather, fuel, and backup plans first.","Right in practice; no regulatory basis."],
 ["W","Yes — every occupant needs an approved restraint, which is why baskets have handles.","Handles aren't seat belts, and balloons are excepted."],
 ["W","No belts, and 91.103 only requires a weather briefing for flights away from the airport.","91.103 covers all flights and more than weather."]]},

{id:"II-E-4",a:"II",t:"E",d:2,ref:"Sectional chart legend; AIM 3-2; 14 CFR 91.130/91.129",
 q:"On the sectional near your launch field there's a magenta vignette and a dashed blue circle. What do they tell you?",
 m:"A magenta vignette (shaded band) marks Class E airspace beginning at 700 ft AGL; outside it, Class E typically begins at 1,200 AGL. A dashed blue line is a Class D surface area — two-way radio communication with the tower is required before entry, and the ceiling is shown in brackets (in hundreds of feet MSL).",
 ans:[["B","Class E begins at 700 ft AGL inside the vignette; dashed blue is Class D — call before entering.","Correct chart interpretation."],
 ["S","The faded magenta means controlled airspace starts lower, and the blue dashes are a tower's airspace.","Correct gist without altitudes."],
 ["W","Magenta vignette is Class C; the dashed blue circle is Class E to the surface, no call required.","Misreads both symbols."],
 ["W","Magenta vignette marks a TFR; dashed blue marks a restricted area to avoid entirely.","TFRs aren't charted that way; blue dashes are Class D."]]},

{id:"II-F-3",a:"II",t:"F",d:2,ref:"14 CFR 61.35; 61.123(c); AC 61-65",
 q:"Your student wants to take the commercial balloon knowledge test. What do you need to give them?",
 m:"An endorsement from an authorized instructor certifying they completed the required ground training or a home-study course and are prepared for the knowledge test (61.35, 61.123(c)), along with proper identification. After the test, the AKTR's missed knowledge areas are reviewed before the practical test, with an endorsement.",
 ans:[["B","An endorsement certifying the training or home study, plus ID at the test.","Matches 61.35/61.123(c)."],
 ["S","A logbook sign-off saying they're ready for the written, and then we review what they miss.","Correct gist."],
 ["W","No endorsement — the knowledge test is open to anyone who shows a pilot certificate.","Commercial knowledge test requires an instructor endorsement or alternative."],
 ["W","An endorsement on the back of their private certificate, valid for 60 days.","Endorsements go in the logbook/records, not on the certificate."]]},

// ---------- AREA III ----------
{id:"III-A-8",a:"III",t:"A",d:1,ref:"14 CFR 61.57(a); 61.56(d)",
 q:"What recent experience do you need to carry passengers, and does today's checkride count for anything?",
 m:"61.57(a): three takeoffs and three landings within the preceding 90 days as sole manipulator of the controls in an aircraft of the same category and class (lighter-than-air balloon). Passing a practical test for a certificate or rating satisfies the flight review requirement (61.56(d)) for another 24 calendar months.",
 ans:[["B","Three launches and landings in 90 days; today also counts as a flight review.","Correct 61.57 and 61.56(d)."],
 ["S","Three takeoffs and landings in the last 90 days, and I think a checkride resets the flight review.","Correct but uncertain."],
 ["W","Three launches and landings in 90 days, but only if each flight lasts at least 30 minutes.","No duration requirement exists."],
 ["W","Nothing extra — passenger currency applies to airplanes, not balloons.","61.57 applies to all category/class combinations."]]},

{id:"III-A-9",a:"III",t:"A",d:3,ref:"14 CFR Part 91; 61.133; 119.1(e)(2); 91.147",
 q:"Under what rules does your ride business operate? Do you need an air carrier certificate or a 91.147 letter of authorization?",
 m:"Hot air balloon ride operations are conducted under Part 91 operating rules, with the pilot exercising commercial privileges (61.133) — so a second-class medical and the 100-hour inspection apply. No Part 119 air carrier certificate is required. The 91.147 Letter of Authorization applies to nonstop commercial air tours in airplanes or helicopters (119.1(e)(2)), not balloons.",
 ans:[["B","Part 91 with commercial privileges — no air carrier certificate or 91.147 letter.","Correct framework."],
 ["S","It's Part 91 with a commercial pilot — I'm pretty sure balloon rides don't need a 135 certificate.","Right answer, missing the 91.147 piece."],
 ["W","Part 135, since it's passengers for hire — the company needs an air carrier certificate.","Balloon rides aren't conducted under Part 135."],
 ["W","Part 91 plus a 91.147 letter of authorization, required for any air tour that carries paying passengers.","91.147 applies to airplanes and helicopters."]]},

{id:"III-A-10",a:"III",t:"A",d:2,ref:"14 CFR 91.403, 39; AC 39-7",
 q:"What's the difference between an airworthiness directive and a manufacturer's service bulletin for your balloon?",
 m:"ADs are regulatory (14 CFR 39): compliance is mandatory, and the owner/operator is responsible (91.403); compliance is recorded in the maintenance records. Service bulletins are manufacturer recommendations — not mandatory for Part 91 operators unless incorporated by an AD or required by the flight manual/limitations — though following them is good practice.",
 ans:[["B","ADs are mandatory (Part 39) and logged; service bulletins are advisory unless an AD requires them.","Correct distinction."],
 ["S","ADs are the FAA telling you to fix it; bulletins are the maker's suggestions you should still follow.","Correct gist."],
 ["W","Both are mandatory for commercial operations, since ride flights carry passengers for hire.","SBs aren't automatically mandatory for Part 91 operations."],
 ["W","Service bulletins are mandatory; ADs are recommendations unless the inspector flags them.","Reversed."]]},

{id:"III-B-5",a:"III",t:"B",d:2,c:1,ref:"FAA-H-8083-28 — METAR; BFH",
 q:"The 0600 METAR shows 27008G18KT. Talk me through what that means for a ride flight.",
 m:"Wind from 270° true at 8 knots, gusting 18 — a 10-knot gust spread. Gusts make inflation, launch, and landing hazardous and signal mechanical turbulence/mixing; winds may increase as the morning heats. Compare to my personal minimums, the operator's limits, and the manufacturer's guidance — most ride pilots would cancel.",
 ans:[["B","West at 8 gusting 18 — a 10-knot spread signals mixing; likely a cancel for rides.","Correct decode and risk judgment."],
 ["S","Wind from the west around 8 knots with gusts to 18 — that's pretty sporty for passengers.","Correct decode, softer decision."],
 ["W","270 degrees at 8 knots with a gust limit of 18 knots forecast for the afternoon only.","Misreads the METAR as a forecast."],
 ["W","Wind toward 270 degrees at 8 knots, gusts 18 — fine, since the steady wind is under 10 knots.","Direction is FROM, and gusts can't be ignored."]]},

{id:"III-B-6",a:"III",t:"B",d:1,ref:"BFH; FAA-H-8083-28",
 q:"Why do balloons fly around sunrise and sunset, and what's a pibal?",
 m:"Shortly after sunrise and in the couple of hours before sunset, surface winds are usually lightest and the air most stable, with minimal thermal activity. A pibal (pilot balloon) is a small helium balloon released at the launch site; watching its direction and speed as it rises shows the actual wind profile at various altitudes.",
 ans:[["B","Stable air, light winds, no thermals; a pibal is a small helium balloon showing winds aloft.","Correct."],
 ["S","The air is calmer early and late, and the little helium balloon shows which way the wind goes up high.","Correct gist."],
 ["W","Cooler air gives more lift; a pibal is a weighted streamer that measures the surface gust spread.","Pibals measure winds aloft, and the main reason is stability."],
 ["W","FAA rules limit balloons to twilight hours; a pibal is a pressure barometer used for altimeter setting.","No such rule, and wrong definition."]]},

{id:"III-C-2",a:"III",t:"C",d:2,ref:"PTS III.C; BFH",
 q:"Planning a flight from the county fairgrounds: what will you identify along the possible trajectories?",
 m:"Airspace (e.g., Class C/D boundaries, TFRs), obstructions and power lines (towers on the sectional, transmission corridors on maps), terrain and water, populated/congested areas (91.119), sensitive areas (livestock, wildlife refuges), and suitable landing areas with road access — for each wind direction at the altitudes I might fly.",
 ans:[["B","Airspace, TFRs, towers and wires, congested areas, livestock, landing fields.","PTS elements covered."],
 ["S","Any airspace, tall towers, power lines, and where I could land with the chase crew getting in.","Correct essentials."],
 ["W","Only the landing site at the end, since the track will change once airborne anyway.","PTS requires identifying airspace, obstructions, and landing areas along the route."],
 ["W","Airspace and the final landing field — power lines aren't charted, so they can't be planned.","Major lines and towers are visible on charts and maps."]]},

{id:"III-C-3",a:"III",t:"C",d:3,ref:"PTS III.C.3; FAA-H-8083-28",
 q:"Winds aloft: surface calm, 1,000 ft 090° at 6, 2,000 ft 180° at 10. Your target landing area is due north of launch. How do you plan?",
 m:"Winds FROM 090 carry me west; FROM 180 carry me north. So: launch and climb to about 2,000 ft for the northbound leg, use lower layers to adjust east-west position, then descend through the layers to approach — allowing for the westward drift through 1,000 ft. Verify layers with a pibal before launch.",
 ans:[["B","2,000 ft carries me north; 1,000 ft pushes west — use both, and pibal it.","Correct reciprocal reasoning."],
 ["S","Go up high to ride the south wind north, and account for drifting west on the way up and down.","Correct reasoning informally."],
 ["W","Stay at 1,000 feet — wind from 090 will carry me north toward the target area.","090 wind carries the balloon west."],
 ["W","Climb to 2,000 feet to ride the 180 wind south toward the target area.","A wind FROM 180 carries the balloon north, not south."]]},

{id:"III-D-5",a:"III",t:"D",d:2,ref:"PTS III.D.2; Balloon Flight Manual",
 q:"You have 45 gallons usable, you plan on 15 gallons per hour, and you want to land with 15 gallons. How long can you fly?",
 m:"Usable fuel minus reserve: 45 − 15 = 30 gallons. At 15 gal/hr that's 2.0 hours planned flight time. Actual burn varies with load, ambient temperature, and maneuvering — monitor the burn rate in flight and adjust the commit-to-land point.",
 ans:[["B","Two hours — 30 gallons above the reserve at 15 an hour; watch the real burn.","Correct math with the caveat."],
 ["S","About two hours, since I keep a tank's worth back and burn roughly fifteen an hour.","Correct number with loose reasoning."],
 ["W","Three hours — 45 gallons at 15 per hour, with the reserve counted as part of the flight time.","Ignores the planned reserve."],
 ["W","One hour — burn rate doubles on landing approaches, so plan on 30 gallons per hour throughout.","Arbitrary assumption contradicting the stated planning rate."]]},

{id:"III-D-6",a:"III",t:"D",d:2,ref:"BFH; Balloon Flight Manual",
 q:"You add one more passenger. What happens to envelope temperature, fuel burn, and margins?",
 m:"More weight requires more lift — a higher envelope temperature for equilibrium — which increases fuel burn, reduces the margin to maximum continuous and never-exceed temperatures, slows climb response, and reduces margins for obstacle clearance and landing aborts. Recheck the load chart.",
 ans:[["B","Higher envelope temperature, more fuel burn, less margin to limits — recheck the load chart.","Correct cause and effect."],
 ["S","It's heavier, so I'll burn more and run hotter, and the balloon won't climb as quickly.","Correct effects without the limits check."],
 ["W","Nothing significant — balloons have so much lift that one passenger is within the margin of error.","Every pound changes required temperature."],
 ["W","Fuel burn goes up but envelope temperature stays the same; the burner just cycles more often.","Burner cycling raises the average envelope temperature."]]},

{id:"III-E-4",a:"III",t:"E",d:2,ref:"BFH; Balloon Flight Manual",
 q:"What does your fuel pressure gauge tell you, and what would a low reading mean?",
 m:"Tank/line pressure feeding the burner, which depends mostly on propane temperature (vapor pressure) and any nitrogen pressurization. Low pressure means weaker burner output and slower response: cold fuel, an unpressurized tank in cold weather, a nearly empty nitrogen-pressurized tank, a partially closed valve, or a restriction. Switch tanks and plan accordingly.",
 ans:[["B","Line pressure, driven by fuel temperature; low means weak burner output — switch tanks.","Correct interpretation."],
 ["S","How much push the fuel has — if it's low, the burner won't put out as much heat, so I'd switch.","Correct gist."],
 ["W","Fuel quantity remaining — pressure drops in step with the fuel level in the tank.","Vapor pressure depends on temperature, not quantity."],
 ["W","Envelope pressure — a low reading means the parachute vent is leaking and needs reseating.","Confuses the fuel gauge with the envelope."]]},

// ---------- AREA IV ----------
{id:"IV-A-4",a:"IV",t:"A",d:2,ref:"PTS IV; VII.F",
 q:"Teach me the high-wind landing. What are the common errors?",
 m:"Objective: land safely in high wind within a suitable area, with occupants briefed and the envelope deflated promptly. Common errors: choosing a field without enough run-out, incomplete passenger briefing, late fuel/pilot shutdown, late deflation (dragging), approaching too fast or too high, and letting occupants exit before the basket stops.",
 ans:[["B","Short run-out, weak briefing, late fuel shutdown, late deflation, and exiting before it stops.","Covers PTS elements and common errors."],
 ["S","Picking a field that's too small and not briefing well — and waiting too long to open the top.","Partial list."],
 ["W","The most common error is deflating too early; keep the envelope up until the basket stops.","Late deflation causes dragging."],
 ["W","Not keeping the pilot lights burning on touchdown, so you can't relaunch if the field is bad.","Pilot lights should be extinguished per manual."]]},

{id:"IV-A-5",a:"IV",t:"A",d:2,ref:"PTS IV; VII.B",
 q:"Teach the launch over an obstacle. What instructional aids would you use?",
 m:"Objective, elements (height, distance, wind, false lift, preheat, decisive burn), common errors (launching too light, relying on false lift, hesitating), and completion standards. Aids: a whiteboard sketch of the climb gradient vs. obstacle, a simple time-distance calculation, and video of a launch for debrief.",
 ans:[["B","A climb-gradient sketch, a time-distance example, and launch video to debrief.","Covers lesson elements and aids."],
 ["S","I'd draw the trees and the climb path on a whiteboard and go over why false lift fools you.","Good aid, partial coverage."],
 ["W","No aids — this maneuver can only be taught by demonstration in strong wind.","PTS expects aids where appropriate; it can be taught on the ground."],
 ["W","A wind sock only, since the lesson is about reading surface wind direction.","Misses height, distance, false lift, and climb rate."]]},

// ---------- AREA V ----------
{id:"V-A-2",a:"V",t:"A",d:2,ref:"PTS V.A; BFH",
 q:"You arrive at a familiar launch field and the farmer has turned cattle into it. What now?",
 m:"Don't launch there. Livestock can panic, injure themselves, or damage fences; the landowner relationship and permission are critical. Choose an alternate launch site with permission, considering the same size, surface, obstacles, and downwind landing options.",
 ans:[["B","Don't launch there — livestock and the owner come first. Use an approved alternate.","Correct judgment."],
 ["S","I'd go somewhere else, since cows and a burner don't mix and I don't want to upset the farmer.","Correct in plain terms."],
 ["W","Launch quickly with minimal burns — cattle get used to balloons after the first burn or two.","Livestock stress and injury risk."],
 ["W","Have the crew herd the cattle to one corner of the field, then launch from the far end.","Disregards the owner's use of the property."]]},

{id:"V-B-2",a:"V",t:"B",d:2,c:1,ref:"PTS V.B; BFH",
 q:"Your crown line handler is a first-time volunteer. What exactly do you tell them?",
 m:"Wear gloves; take position downwind at the end of the crown line; during cold inflation hold tension to keep the envelope steady; as it rises, walk toward the basket, controlling but never stopping it; never wrap the line around a hand, wrist, or body; if you start to be lifted, let go immediately; stay clear of the burner.",
 ans:[["B","Gloves, tension, walk it in, never wrap it, let go if lifted, avoid the burner.","Complete safety briefing."],
 ["S","Hold the rope steady and walk it toward the basket as it goes up — and don't wrap it on your hand.","Correct core, missing let-go rule and gloves."],
 ["W","Hold it as tightly as you can and don't let go until the balloon is fully upright, no matter what.","Handlers have been lifted and injured."],
 ["W","Tie the line to your belt so your hands are free to help the mouth crew if needed.","Never attach the line to a person."]]},

{id:"V-C-2",a:"V",t:"C",d:2,c:1,ref:"PTS V.C; Balloon Flight Manual",
 q:"How do you verify the envelope-to-basket attachment during assembly?",
 m:"Follow the manual: correct number and routing of cables, each attached to the correct load frame point with the specified carabiner/fastener, gates closed and locked, no twisted or crossed cables, burner frame secured, and a second-person check or checklist before inflation. Verify again in the pre-launch check.",
 ans:[["B","Per the manual — correct cables and points, carabiners locked, no twists, then a second check.","Matches PTS V.C.4–5."],
 ["S","Make sure every cable is clipped to the right spot and every carabiner is closed before inflating.","Correct core."],
 ["W","Hand-tight carabiners are fine; locking them makes a fast emergency disconnect impossible.","Carabiners must be locked as specified."],
 ["W","The crew chief handles attachments; the pilot only checks the burner and the fuel system.","PTS holds the pilot responsible for assembly."]]},

{id:"V-D-2",a:"V",t:"D",d:2,c:1,ref:"PTS V.D; Balloon Flight Manual",
 q:"During preflight you find a 2-inch hole in the envelope near the crown. Can you fly?",
 m:"Not until it's evaluated against the manufacturer's damage limits in the flight manual/ICA. Location matters: damage near the crown, at load tapes, or in high-stress panels is more critical than near the mouth. If outside limits or within a no-damage zone, it must be repaired by an authorized person (or as preventive maintenance only if allowed) before flight.",
 ans:[["B","Only if it's within the manufacturer's damage limits for that location — else repair it.","Correct process."],
 ["S","Probably not — damage near the top is the worst place, so I'd check the manual or get it fixed.","Correct direction, less precise."],
 ["W","Yes — two inches is small and the parachute top covers that area during flight anyway.","Ignores damage limits and location."],
 ["W","Yes, if I tape it with fabric repair tape, since that counts as preventive maintenance.","Repair must comply with manual limits and Part 43."]]},

{id:"V-E-2",a:"V",t:"E",d:2,c:1,ref:"PTS V.E; BFH",
 q:"Halfway through cold inflation a gust rolls the envelope. What do you do?",
 m:"Stop the inflation — no hot burns into a distorted or rolling envelope. Have crew control the mouth and crown line, let the gust pass, reassess wind and conditions (gusts may mean it's a no-go), and reposition if needed. Only resume when the envelope is stable and conditions are acceptable.",
 ans:[["B","Stop — no burns into a rolling envelope; control it, reassess the wind, resume only when stable.","Correct priorities."],
 ["S","Hold off burning until the envelope settles down and make sure the wind isn't too strong to continue.","Correct essentials."],
 ["W","Burn quickly to get it upright before the next gust — a standing balloon resists wind better.","Burning into a rolling envelope risks fabric burns and injury."],
 ["W","Have the crown line handler pull hard against the gust to keep the envelope from rolling.","Can injure the handler and doesn't stabilize the envelope."]]},

{id:"V-F-2",a:"V",t:"F",d:2,c:1,ref:"PTS V.F; 14 CFR 91.3",
 q:"In flight, a passenger climbs onto the basket edge for a better photo. What do you do?",
 m:"Immediately direct them back down — passengers must stay inside the basket. As PIC (91.3) I'm responsible for safety; an occupant on the rim risks falling and shifts weight. Re-brief everyone, and if they won't comply, land at the first suitable site.",
 ans:[["B","Order them down now, re-brief everyone, and land early if they won't comply — I'm PIC.","Correct and firm."],
 ["S","Tell them to get down right away and remind everyone to stay inside the basket.","Correct action."],
 ["W","Let it go if we're above 500 feet, since there's nothing to hit if they fall — just hold on tight.","Fall hazard regardless of altitude."],
 ["W","Allow it if they hold a suspension cable, since the cables are rated for far more than one person.","Cable strength isn't the issue; fall and control are."]]},

{id:"V-G-2",a:"V",t:"G",d:1,ref:"PTS V.G.7; BFH",
 q:"What is equilibrium, and how do you know you've reached it before launch?",
 m:"Equilibrium is when lift equals weight — the balloon neither rises nor sinks. Before launch, heat until the basket becomes light: with crew hands off (or the tie-off just slack) it stays in place; a little more heat gives positive lift for launch.",
 ans:[["B","Lift equals weight — hands off, the basket neither rises nor settles; then add heat to go.","Correct definition and check."],
 ["S","When the basket starts to feel light and just floats there — then I add a bit more heat to go.","Correct practical description."],
 ["W","When the envelope temperature gauge reads the number printed in the manual for launch.","Equilibrium depends on load and conditions, not one fixed number."],
 ["W","When the tie-off line is tight, showing the balloon is pulling upward with positive lift.","A taut tie-off means positive lift, not equilibrium."]]},

// ---------- AREA VI ----------
{id:"VI-A-3",a:"VI",t:"A",d:2,ref:"AIM 4-2; 14 CFR 91.129",
 q:"Your track will clip a Class D surface area. Give me your call to the tower.",
 m:"Before entry: 'Anytown Tower, Balloon N1234X, four miles west at two thousand, drifting east at eight knots, request transit through your Class D, will remain above one thousand five hundred.' Establish two-way communication (the tower responding with my call sign) before entering, and say 'unable' to any instruction I can't fly.",
 ans:[["B","Who, who I am, where, altitude and drift, request — then wait for my call sign back.","Correct format and communication rule."],
 ["S","Tower, balloon tail number, where I am and how high, that I'm drifting in — can I come through?","Correct elements informally."],
 ["W","Enter first and call once inside — towers expect balloons and can't stop them anyway.","Two-way comms required before entering Class D."],
 ["W","Call ground control, since balloons are slow-moving and handled like surface traffic.","Airborne traffic talks to tower."]]},

{id:"VI-A-4",a:"VI",t:"A",d:2,ref:"AIM 4-2; BFH",
 q:"You lose radio contact with your chase crew mid-flight. What's your plan?",
 m:"Try alternate means: cell phone/text, the backup radio, a relay through another balloon. Fly a predictable track, choose a landing site near roads where the crew can find me, and land within the briefed time window. The crew follows the pre-briefed lost-contact plan (last known track, landing time).",
 ans:[["B","Phone or relay, fly predictably, land near roads within the briefed window.","Correct, pre-briefed approach."],
 ["S","Call them on my cell, and if that fails, land somewhere easy to find near a road.","Correct gist."],
 ["W","Keep flying until contact is restored so the crew can find me before I commit to a field.","Extends the flight unnecessarily; fuel and options shrink."],
 ["W","Switch to the tower frequency and ask ATC to relay to my chase crew by phone.","ATC isn't a relay for ground crews."]]},

// ---------- AREA VII ----------
{id:"VII-A-2",a:"VII",t:"A",d:2,c:1,ref:"PTS VII.A; BFH",
 q:"You release the quick release and the balloon lifts a few feet, then settles back down. What happened and what now?",
 m:"Not enough true buoyancy — likely false lift or insufficient heat. Don't keep bouncing toward obstacles: either add heat decisively for a positive climb if the downwind path is clear, or have the crew hold the basket and reset. Recheck the load and conditions.",
 ans:[["B","Too little real lift — burn decisively if clear, or have crew hold it and reset.","Correct diagnosis and options."],
 ["S","It wasn't hot enough — I'd burn more before trying again, with the crew holding on.","Correct action."],
 ["W","Normal — a bounce helps the envelope shape up; let it hop along until it climbs out.","Hopping toward obstacles is hazardous."],
 ["W","Vent to settle it firmly, then re-release with the same heat once the wind calms.","Same heat repeats the failure."]]},

{id:"VII-C-2",a:"VII",t:"C",d:2,ref:"PTS VII.C.2; BFH",
 q:"From 800 feet, how do you figure out the surface wind at your chosen field?",
 m:"Watch smoke, flags, dust, tree movement, ripples on water, and crop movement; observe other balloons' tracks; drop to a lower altitude to see how the track changes; and ask the crew for observations. Surface wind often differs in speed and direction from the wind at altitude.",
 ans:[["B","Smoke, flags, water ripples, trees, other balloons — and a lower look to see the track change.","Correct cues."],
 ["S","Look for flags or smoke near the field, and maybe ask the crew what the wind is doing there.","Correct core."],
 ["W","Use the winds aloft forecast for the surface level — it's accurate enough near the ground.","Surface winds aren't forecast that way and vary locally."],
 ["W","Assume it matches my current drift at 800 feet, since winds near the ground follow the upper flow.","Surface winds commonly differ."]]},

{id:"VII-C-3",a:"VII",t:"C",d:3,c:1,s:1,ref:"PTS VII.C.7; BFH",
 q:"On final, 200 feet up, you realize the field you picked has a hidden ditch and fence near the touchdown point. Decide.",
 m:"Abort now — burn early and decisively given lag, climb to a safe altitude with margin over obstacles, then select another field. Re-brief passengers and check fuel. A late decision near the ground leaves no room for the burner to take effect.",
 ans:[["B","Abort now with an early, decisive burn, climb with margin, pick a new field, and re-brief.","Correct timing and action."],
 ["S","Go around — burn and climb back up, then find a better spot further on.","Correct decision, less detail."],
 ["W","Continue and touch down short of the ditch — once committed below 200 feet, never abort.","No such rule; late abort window is what matters."],
 ["W","Vent harder to land before the ditch, then use the drop line to hold the basket in place.","Rushed descent into a hazard."]]},

{id:"VII-D-2",a:"VII",t:"D",d:2,ref:"PTS VII.D; BFH",
 q:"What makes a steep approach riskier than a shallow one, and how do you manage it?",
 m:"Higher descent rate near the ground means less time to arrest the descent given burner lag, possible envelope distortion, and a harder touchdown. Manage it with a planned arrest point well above the ground, smaller vent inputs, early burns, and a firm abort decision.",
 ans:[["B","Higher sink near the ground plus lag — arrest high, burn early, abort early.","Correct risk and management."],
 ["S","You're coming down faster, so you've got to start burning sooner to stop in time.","Correct core."],
 ["W","It's riskier only in high wind; in calm air a steep approach is actually the safest option.","Arresting the descent is the key risk in any wind."],
 ["W","Steep approaches are safer because less time near obstacles means less risk overall.","Ignores arrest-rate risk."]]},

{id:"VII-E-2",a:"VII",t:"E",d:2,ref:"PTS VII.E; BFH",
 q:"When do you use a drop line, and how do you brief the crew on it?",
 m:"In light winds, a drop line lets the crew guide the basket to a precise spot or around obstacles. Brief: grab the line only when told, use gloves, never wrap it around hands or body, don't tie it to a vehicle or object, keep it clear of obstacles and the burner, and let go if lifted.",
 ans:[["B","Light winds for precise positioning — gloves, never wrap or tie it off, and let go if lifted.","Correct use and safety brief."],
 ["S","For calm landings so the crew can walk me in — I'd tell them to wear gloves and not wrap it.","Correct core."],
 ["W","In high winds so the crew can stop the basket from dragging after touchdown.","Crew can't hold a balloon in high wind; injury risk."],
 ["W","Tie it to the chase vehicle so the balloon can be towed to the trailer after landing.","Never tie off to a vehicle in flight."]]},

{id:"VII-F-2",a:"VII",t:"F",d:2,c:1,ref:"PTS VII.F.8; BFH",
 q:"Why do you extinguish pilot lights and shut off fuel before a high-wind touchdown?",
 m:"A high-wind landing may tip the basket over and drag it, putting the burner close to the ground, fabric, and occupants. An open flame and pressurized fuel lines in a tipping basket create a fire and burn hazard. Shut off fuel and extinguish pilot lights per the flight manual so nothing can ignite as the basket drags.",
 ans:[["B","A tipping, dragging basket puts flame and fuel near fabric and people — fire risk.","Correct reason."],
 ["S","So if the basket tips over, there's no flame or fuel feeding a fire near the passengers.","Correct gist."],
 ["W","To save fuel for the recovery and keep the tanks from venting on the ride home.","Not the reason."],
 ["W","The FAA requires it on every landing, regardless of wind, for noise abatement near farms.","Not a noise rule; it's per the manual for safety."]]},

{id:"VII-B-2",a:"VII",t:"B",d:3,c:1,s:1,ref:"PTS VII.B; ADM",
 q:"Your only launch option has power lines 400 feet downwind and wind at 8 knots. The passengers are excited. Go or no-go?",
 m:"Calculate: 400 ft at 8 kt (~810 ft/min) gives about 30 seconds — I'd need a strong, assured climb with margin and no false-lift dependence. If I can't be certain of clearing the lines with a large margin at this load and temperature, it's a no-go or a relocation. Passenger enthusiasm is an external pressure, not a factor.",
 ans:[["B","About 30 seconds to the wires — unless clearance is assured, relocate or cancel.","Correct analysis and ADM."],
 ["S","Only if I'm sure I can climb way over the lines in time — otherwise we find a different field.","Correct decision rule."],
 ["W","Go — balloons climb faster than they drift, so 400 feet is plenty at any normal load.","Unfounded assumption."],
 ["W","Go, but launch light and let the wind lift us over the wires by the time we reach them.","Relies on false lift."]]},

// ---------- AREA VIII ----------
{id:"VIII-A-2",a:"VIII",t:"A",d:2,ref:"PTS VIII.A; Balloon Flight Manual",
 q:"Why does your manual limit the maximum rate of climb?",
 m:"High climb rates create airflow over the crown that can distort the envelope and force the parachute vent, increase envelope temperatures from heavy burning, reduce time to detect traffic above (blind spot), and risk overshooting altitude or airspace. Stay within the manual's limits.",
 ans:[["B","Crown distortion, overtemp from heavy burns, and climbing into traffic above.","Correct reasons."],
 ["S","Going up too fast can deform the top and overheat the envelope — plus you can't see above.","Correct gist."],
 ["W","To conserve fuel — the climb limit exists only to keep burn rates economical.","Not the safety rationale."],
 ["W","Fast climbs reduce air density inside the envelope, causing a sudden loss of all lift.","Physically incorrect."]]},

{id:"VIII-B-2",a:"VIII",t:"B",d:2,ref:"PTS VIII.B; BFH",
 q:"You're holding level at 1,500 feet when the vario shows a 100 fpm descent starting. What's your response?",
 m:"Respond to the trend immediately with a moderate burn, anticipating lag — then reduce once the vario shows the descent arresting, so I don't overshoot into a climb. Small, timely corrections keep altitude within ±50 ft.",
 ans:[["B","Burn now to catch the trend, then ease off as the vario flattens so I don't overshoot.","Correct anticipation."],
 ["S","Give it a burn right away and watch the vario so I don't end up climbing too much.","Correct gist."],
 ["W","Wait until the altimeter confirms a 50-foot loss before burning, to avoid chasing the needle.","Too late given lag."],
 ["W","Make a long burn until the vario shows a strong climb, then vent back to level.","Yo-yo flying; overburn then overvent."]]},

{id:"VIII-C-2",a:"VIII",t:"C",d:2,ref:"PTS VIII.C; BFH",
 q:"Cooling descent versus vented descent — when would you use each?",
 m:"Cooling descent (reduced or no burning) is gradual, fuel-efficient, and keeps the vent closed — good for gentle transitions. A vented descent starts the descent quickly and allows a faster rate when needed — for example to reach a lower wind layer or begin an approach — but requires care not to overvent.",
 ans:[["B","Cooling for gentle, efficient descents; venting to start or speed one up.","Correct comparison."],
 ["S","Cooling is slower and smoother; venting gets you down faster when you need it.","Correct core."],
 ["W","Always vent — cooling descents are unpredictable and can't be controlled within PTS tolerance.","Cooling descents are standard technique."],
 ["W","Cooling descents are faster because the whole envelope cools at once, unlike venting.","Reversed."]]},

{id:"VIII-D-2",a:"VIII",t:"D",d:3,c:1,ref:"PTS VIII.D.4; BFH",
 q:"You're descending at 900 fpm and see power lines ahead at your altitude. Walk me through recovery.",
 m:"Start a strong, continuous burn immediately — lag and momentum mean the descent continues for some time. Monitor envelope temperature, keep burning until the vario shows the descent arrested and a climb starting, then manage to a safe altitude well above the lines. If clearance is in doubt, prepare for contact procedures.",
 ans:[["B","Burn hard now and keep at it until the vario shows a climb; watch envelope temp.","Correct priorities and timing."],
 ["S","Burn right away and keep at it until I'm going up and safely above the wires.","Correct core."],
 ["W","Vent to steepen the descent and slip under the lines before they get close.","Going under wires is deadly."],
 ["W","Short, pulsed burns to avoid overheating the envelope, then reassess in 30 seconds.","Too little, too late."]]},

{id:"VIII-E-2",a:"VIII",t:"E",d:2,ref:"PTS VIII.E.3; BFH",
 q:"Contour flying over a tree line on a breezy morning — what wind effects do you expect?",
 m:"Mechanical turbulence and rotors on the downwind side of the tree line, possible downdrafts that push the balloon toward the trees, wind shear near the surface, and false lift on the upwind side. Fly with extra clearance, anticipate sink on the lee side, and avoid low contour flying in gusty conditions.",
 ans:[["B","Lee-side turbulence and sink, shear near the surface — fly higher.","Correct effects."],
 ["S","Bumpy air and sinking on the far side of the trees, so I'd give them more room.","Correct gist."],
 ["W","Updrafts on the lee side that lift the balloon, so you can skim the treetops safely.","Lee side tends to sink."],
 ["W","None — wind effects only matter near mountains, not over trees.","Trees produce mechanical turbulence."]]},

{id:"VIII-G-2",a:"VIII",t:"G",d:2,c:1,ref:"PTS VIII.G; special emphasis — wire strike avoidance",
 q:"There's a 400-foot radio tower a mile ahead on your track. What hazards besides the tower itself?",
 m:"Guy wires extending far out from the tower (often a large fraction of the tower's height in each direction), nearly invisible; possible nearby power feeds; and the tower's lighting may not show the wires. Give the entire guy-wire area a wide berth — pass well above or change altitude to change track early.",
 ans:[["B","Nearly invisible guy wires reaching far out — give the whole area a wide berth.","Correct key hazard."],
 ["S","There could be cables holding it up, so I'd stay well clear rather than pass close by.","Correct gist."],
 ["W","None, if I pass 100 feet beside it — the tower's lights mark every part of the structure.","Guy wires aren't lit and extend far out."],
 ["W","Only radio interference, which can disrupt my handheld radio within a mile of the tower.","Misses the physical hazard."]]},

{id:"VIII-H-2",a:"VIII",t:"H",d:2,c:1,ref:"PTS VIII.H; Balloon Flight Manual",
 q:"Mid-tether session, the wind begins gusting above the manual's tether limit. Now what?",
 m:"Stop the tether operation: bring the balloon down, get passengers out safely with crew managing weight, deflate, and control the crowd. Gusts on tether lines create large, sudden loads and violent basket movement; free flight to escape isn't a substitute for the planned procedure.",
 ans:[["B","End it — bring it down, unload with crew on the weight, deflate, crowd back.","Correct."],
 ["S","Shut it down and get everyone off and the envelope down before the wind gets worse.","Correct core."],
 ["W","Let out more tether line so the balloon can ride the gusts higher where it's smoother.","Increases loads and risk."],
 ["W","Release one tether so the balloon can weathervane and reduce the loads on the others.","Unbalanced tethers worsen control."]]},

{id:"VIII-I-2",a:"VIII",t:"I",d:2,ref:"PTS VIII.I; BFH",
 q:"Winter flight, snow on the ground. What landing and passenger considerations change?",
 m:"Snow hides ditches, fences, and rocks; depth affects how the basket stops and recovery access. Fields may be inaccessible to chase vehicles. Passengers need warm clothing and footwear; hypothermia risk if a recovery is delayed. Fuel pressure and lower burner output affect landing control.",
 ans:[["B","Hidden obstacles, hard crew access, cold passengers, weaker burner output.","Covers winter-specific concerns."],
 ["S","Snow hides stuff and the crew may not get in, so passengers need to dress warmly.","Correct core."],
 ["W","Snow makes landings safer because it cushions the basket, so choose snowy fields.","Hidden obstacles and access issues."],
 ["W","No changes — winter only affects the fuel system, not landings or passengers.","Ignores real hazards."]]},

{id:"VIII-J-2",a:"VIII",t:"J",d:2,ref:"PTS VIII.J; FAA-H-8083-28",
 q:"You see lenticular clouds over the ridge before a mountain flight. What does that tell you?",
 m:"Strong winds aloft flowing over the terrain creating mountain waves, with likely severe turbulence and rotors on the lee side and strong downdrafts. It's a strong no-go indicator for balloon flight in that area.",
 ans:[["B","Mountain wave — strong winds aloft, lee-side rotors and downdrafts. A no-go for balloons.","Correct interpretation."],
 ["S","Strong wind up high over the mountains — that means rough air, so I wouldn't fly.","Correct decision."],
 ["W","Stable, calm conditions — lenticulars form only when the air is completely still.","Lenticulars indicate strong winds."],
 ["W","Moisture only — lenticulars mean possible light rain, so bring a cover for the basket.","Misses the turbulence indication."]]},

// ---------- AREA IX ----------
{id:"IX-A-3",a:"IX",t:"A",d:2,ref:"PTS IX; BFH",
 q:"How do you verify your position and track when the landscape all looks the same?",
 m:"Correlate distinctive features (roads, rivers, railroads, towers, towns, water tanks) to chart symbols; use GPS for position, groundspeed, and track; compare with the planned trajectory; and keep the crew updated. Check altitude restrictions relative to position.",
 ans:[["B","Match roads, rivers, rails, and towers to the chart, and cross-check with GPS.","Correct technique."],
 ["S","Use GPS mostly, and look for big things like highways or towns on the map to confirm.","Correct core."],
 ["W","Rely on the chase crew to tell me where I am — they can see road signs from the ground.","PTS requires the pilot to verify position."],
 ["W","Use the altimeter and compass heading to dead-reckon position over flat terrain.","Balloons have no heading control; DR by heading doesn't apply."]]},

{id:"IX-A-4",a:"IX",t:"A",d:3,s:1,ref:"PTS IX; 14 CFR 91.131, 91.225(e)",
 q:"Your track bends toward a Class C boundary and your fuel is at 40%. Lay out your options.",
 m:"Change altitude to find a wind carrying me away from the Class C, if available. Otherwise, land before the boundary while fuel and landing options remain. Without ADS-B/transponder I can't enter Class C or overfly its ceiling; with equipment I'd still need two-way communications before entry. Decide early.",
 ans:[["B","Find a wind away from it; if none, land short while fuel and fields remain — don't drift in.","Correct prioritized options."],
 ["S","Try a different altitude to steer away, and if that doesn't work, land before I get there.","Correct core."],
 ["W","Call approach and enter — balloons are exempt from Class C entry rules due to limited steering.","No such exemption."],
 ["W","Climb above the Class C ceiling, since equipment rules don't apply above controlled airspace.","Exception requires staying below the ceiling."]]},

// ---------- AREA X ----------
{id:"X-A-5",a:"X",t:"A",d:2,c:1,ref:"PTS X.A.5; BFH",
 q:"Your parachute vent doesn't reseat after a pull and you're losing heat. What do you do?",
 m:"Try to reseat it: release the vent line fully, give a burn to build internal pressure (pressure seats the parachute), and check for snagged lines. If it won't reseat, compensate with heat within temperature limits and land at the first suitable site.",
 ans:[["B","Release the line, burn to build pressure and reseat it; if not, compensate and land soon.","Correct procedure."],
 ["S","Let go of the line and burn so the top pops back into place — then land if it won't stay.","Correct core."],
 ["W","Pull the vent line harder to free the top and then release it quickly to snap it closed.","Opens the vent further."],
 ["W","Ignore it — a partly open vent just lowers fuel efficiency and causes no real hazard.","Uncontrolled heat loss can mean an uncommanded descent."]]},

{id:"X-A-6",a:"X",t:"A",d:2,ref:"BFH; Balloon Flight Manual",
 q:"A passenger collapses during the flight. What do you do?",
 m:"Fly the balloon first, then assess: get help from other passengers, use the first aid kit, and call 911 (or have the crew call) with your location. Land at the first suitable site with good access for emergency vehicles. Brief the remaining passengers.",
 ans:[["B","Fly first, give first aid, call 911 with my location, land near road access.","Correct priorities."],
 ["S","Get them help from the others, call 911, and land as soon as I can near a road.","Correct core."],
 ["W","Descend immediately as fast as possible, since speed matters more than the landing site.","Rapid descent risks everyone."],
 ["W","Continue the flight to the planned landing site, where the crew has the first aid kit.","Delays care."]]},

{id:"X-A-7",a:"X",t:"A",d:2,c:1,ref:"PTS X.A; BFH",
 q:"You notice a tear developing near a load tape in flight. Priorities?",
 m:"Monitor the damage closely, avoid aggressive maneuvers and high climb/descent rates, stay within temperature limits (more heat may be needed due to leakage), and land at the first suitable site. Brief passengers for a possibly firm landing. Inspection and repair before further flight.",
 ans:[["B","Monitor it, fly gently within limits, brief everyone, land at the first suitable site.","Correct priorities."],
 ["S","Get down soon and gently, keeping an eye on the tear in case it grows.","Correct core."],
 ["W","Climb higher where the air is cooler and denser, so the envelope needs less heat.","Delays landing with worsening damage."],
 ["W","Vent to reduce pressure on the tear and continue the flight to the planned field.","Venting isn't a fix and the flight should end."]]},

{id:"X-B-2",a:"X",t:"B",d:2,ref:"PTS X.B; BFH",
 q:"You're planning a flight over the Great Lakes shoreline area. What does your emergency gear list add?",
 m:"Flotation (life vests) for all occupants, a means to signal, a waterproofed phone/radio, and a briefing on their use. Plus cold-water considerations: warm clothing, and an emergency blanket. Consider whether the flight should be planned over water at all.",
 ans:[["B","Life vests, signaling gear, waterproofed comms, and cold-water clothing.","Climate/terrain-appropriate gear."],
 ["S","Life jackets and a way to call for help if we end up in the water.","Correct core."],
 ["W","Nothing extra — balloon baskets float, so the basket itself serves as the flotation device.","Baskets aren't flotation devices."],
 ["W","A spare propane cylinder, so I can stay airborne long enough to reach the far shore.","Doesn't address water emergencies."]]},

{id:"X-C-2",a:"X",t:"C",d:3,ref:"PTS X.C.2; BFH",
 q:"For an emergency water landing, why do wind and current direction matter?",
 m:"Wind acting on the envelope can drag the basket across the water; current moves occupants and the basket. Approach so the wind and current carry you toward shore or help, and avoid being dragged by the envelope while people are in the water — control or deflate the envelope per conditions and the manual.",
 ans:[["B","Wind on the envelope drags the basket and current moves people — use both to reach shore.","Correct factors."],
 ["S","The wind and current will move you around, so you want them taking you toward the shore.","Correct core."],
 ["W","They don't — once in the water, the basket stays still because water drag stops all motion.","Envelope drag continues."],
 ["W","Land facing upwind so the envelope acts as a sea anchor, and leave the deflation port closed.","Can lead to dragging occupants."]]},

{id:"X-D-2",a:"X",t:"D",d:2,ref:"PTS X.D; BFH",
 q:"A dust devil crosses a field near your landing site. Effect on your landing?",
 m:"Strong, rotating thermal turbulence with sudden updrafts and gusts — it can distort the envelope, blow out pilot lights, and cause uncommanded climbs or sink near the ground. Avoid it: pick a different field or wait at altitude for it to dissipate, then land early.",
 ans:[["B","Rotating thermal turbulence that can distort the envelope near the ground — avoid that field.","Correct effects and response."],
 ["S","It means rough, rising air there — I'd pick a different field away from it.","Correct core."],
 ["W","A dust devil helps by creating lift, which softens touchdown if you land right after it passes.","Hazard, not help."],
 ["W","Dust devils only affect visibility, so wait for the dust to settle and then land normally.","Misses the turbulence."]]},

// ---------- AREA XI ----------
{id:"XI-A-2",a:"XI",t:"A",d:2,s:1,ref:"PTS XI.A; BFH",
 q:"After landing, an upset farmer says you damaged his soybeans. How do you handle it?",
 m:"Stay calm and courteous, listen, apologize for the impact, and keep the crew off the crop. Exchange contact information, document the damage, and follow the operator's policy for compensation. Landowner relations are essential — leave the field as found and follow up.",
 ans:[["B","Listen, apologize, document it, follow company policy, keep the crew off the crop.","Professional handling."],
 ["S","Apologize, get his contact info, and make sure we don't do more damage getting out.","Correct core."],
 ["W","Explain that federal aviation rules allow emergency landings anywhere, so he can't complain.","Not an emergency and alienates landowners."],
 ["W","Leave quickly to avoid a confrontation, then have the office send a form letter later.","Damages landowner relations."]]},

{id:"XI-B-2",a:"XI",t:"B",d:2,c:1,ref:"PTS XI.B; BFH",
 q:"What are the main hazards during deflation and pack-up?",
 m:"Crew struck or dragged by the envelope in wind; hot air and fabric near the burner; fuel not secured (pilot lights still lit, lines not bled); crew walking on fabric; spectators too close; and vehicle movement near the crew. Brief roles, secure fuel first, and control the area.",
 ans:[["B","Envelope dragging crew, unsecured fuel, people on the fabric, spectators, and vehicles.","Correct hazards."],
 ["S","The envelope moving in the wind, fuel still on, and people getting too close.","Correct core."],
 ["W","None after landing — the flight is over, so pack-up isn't a safety concern for the pilot.","Pilot remains responsible."],
 ["W","Only rain, which damages the fabric, so pack-up should be fast regardless of fuel status.","Ignores primary hazards."]]},

{id:"XI-C-3",a:"XI",t:"C",d:2,c:1,ref:"PTS XI.C; BFH",
 q:"Why is the 80% fill limit important, and what happens if a tank is overfilled?",
 m:"Propane expands significantly as temperature rises. The vapor space allows liquid to expand; an overfilled tank can become liquid-full, sending pressure up rapidly and opening the relief valve, which releases propane — a fire hazard — or causing liquid to reach vapor withdrawal points. Use the fixed liquid level gauge to stop at the limit.",
 ans:[["B","Expansion room as it warms; overfilled tanks vent via the relief valve — fire risk.","Correct physics and hazard."],
 ["S","The extra space lets the fuel expand when it warms up; too full and it can vent propane.","Correct core."],
 ["W","The 80% limit protects the fuel gauge, which can't read the top 20% of the tank.","Not the reason."],
 ["W","Overfilling only reduces efficiency, since liquid propane burns less cleanly than vapor.","Misses the overpressure hazard."]]},

{id:"XI-A-3",a:"XI",t:"A",d:2,ref:"PTS XI.A.3; 14 CFR 91.3",
 q:"During recovery, spectators crowd around the deflating envelope. What's your responsibility?",
 m:"Control the scene: have crew keep spectators back from the envelope, basket, burner, and vehicles; brief anyone helping on what to do; ensure fuel is secured; and maintain property and crowd control throughout the recovery.",
 ans:[["B","Keep spectators clear of envelope, burner, and vehicles; secure the fuel.","Correct supervision."],
 ["S","Have the crew keep people back and make sure nobody gets near the burner or tangled.","Correct core."],
 ["W","None — spectators are on private property at their own risk, so it's the landowner's problem.","PTS assigns supervision to the pilot."],
 ["W","Invite them to help fold the envelope — more hands make a quicker, safer pack-up.","Untrained helpers increase risk without a briefing."]]},

// ---------- additional scenarios ----------
{id:"SC-5",a:"III",t:"D",d:3,c:1,s:1,ref:"PTS III.D; ADM",
 q:"Scenario: 94°F at the launch site, a full basket, and the load chart puts you right at maximum envelope temperature. The passengers have paid. Decision?",
 m:"Reduce the load or don't fly. Being at maximum envelope temperature at launch leaves no margin for climbs, obstacles, aborts, or thermals, and accelerates fabric damage. Rebook a passenger or move to a cooler time. Commercial pressure doesn't change the limits.",
 ans:[["B","Reduce the load or cancel — no margin for aborts, obstacles, or thermals at max temp.","Correct ADM."],
 ["S","I'd take fewer people or reschedule — flying right at the limit leaves nothing in reserve.","Correct decision."],
 ["W","Fly — the load chart includes a safety margin, so being at the limit is still within design.","No margin for maneuvering or contingencies."],
 ["W","Fly, but plan a short, low flight so the envelope never needs extra heat for climbs.","Still no margin for obstacles or aborts."]]},

{id:"SC-6",a:"II",t:"E",d:3,s:1,ref:"14 CFR 91.137–91.145; FDC NOTAM sporting events",
 q:"Scenario: Saturday afternoon flight. Your trajectory passes about 2 miles from a stadium with a college game starting in 45 minutes. Problem?",
 m:"Yes — a standing FDC NOTAM TFR covers major sporting events: roughly 3 NM radius up to 3,000 ft AGL, from 1 hour before to 1 hour after the event. Two miles is inside it, and the TFR is likely already active. Change altitude to change track, land before the TFR, or don't launch on that trajectory.",
 ans:[["B","Yes — a stadium TFR, about 3 NM and 3,000 ft AGL, already active an hour before kickoff.","Correct TFR knowledge."],
 ["S","There's usually a TFR around stadiums during games, so I'd plan to stay well away from it.","Correct caution, less detail."],
 ["W","No — stadium TFRs only apply to drones, not manned aircraft like balloons.","Applies to aircraft operations generally."],
 ["W","No — the TFR doesn't start until kickoff, so I'll be past the stadium in time.","Starts 1 hour before the event."]]},

{id:"SC-7",a:"II",t:"B",d:3,c:1,s:1,ref:"PTS II.B.4; BFH",
 q:"Scenario: Mass ascension. You're at 800 feet; another balloon is climbing directly beneath you. What do you do?",
 m:"Recognize the climbing balloon can't see above its envelope. Avoid descending; if needed, climb to increase separation, and communicate by radio. Lower balloon generally has the right of way by custom, but both pilots are responsible for collision avoidance — I control what I can: stop any descent and climb away.",
 ans:[["B","They can't see me — stop any descent, climb to open separation, and call them on the radio.","Correct action."],
 ["S","Get out of their way by going up a bit and try to raise them on the radio.","Correct core."],
 ["W","Descend to make room, since the lower balloon is climbing and can pass underneath.","Descending into a climbing balloon is the collision."],
 ["W","Hold altitude — I'm higher, so I have the right of way and the climbing balloon must stop.","Lower balloon customarily has right-of-way."]]},

{id:"SC-8",a:"I",t:"F",d:3,s:1,ref:"AIH ch. 3; PTS I.F.2; 91.3",
 q:"Scenario: On a training flight your student freezes during the approach and stops burning. What do you do?",
 m:"Take control immediately with a positive exchange ('I have the flight controls'), fly the balloon safely — burn to arrest the descent, abort if necessary — then talk the student through it on the ground. Afterward, explore the stress reaction, adjust the training plan, and don't move on until confidence returns.",
 ans:[["B","Take control with a positive exchange, fly safely, debrief on the ground.","Correct immediate and instructional response."],
 ["S","Take over right away, get us safe, and talk about what happened once we're down.","Correct core."],
 ["W","Coach them through it verbally so they learn to recover — taking over would undermine them.","Safety first; instruction can wait."],
 ["W","Let them work it out for a few seconds — freezing is normal and they'll come out of it.","Burner lag means seconds matter."]]},

{id:"SC-9",a:"V",t:"F",d:3,s:1,ref:"PTS V.F; special emphasis — aviation security",
 q:"Scenario: A passenger shows up with a large backpack and refuses to say what's inside. Your call?",
 m:"As PIC I'm responsible for the safety and security of the flight. Loose items must be secured and I need to know what's aboard (fuel/fire risk, hazardous materials). If they won't disclose or leave the bag with the crew, they don't fly. Stay calm and professional.",
 ans:[["B","I need to know what's aboard — leave it with the crew or they don't fly; stay professional.","Correct security posture."],
 ["S","Ask them to leave it with the ground crew, and if they won't, they can't come along.","Correct decision."],
 ["W","Let them bring it — passenger belongings are private and searching them isn't the pilot's role.","PIC must manage what's aboard."],
 ["W","Allow it if they hold it on their lap during the whole flight, so it can't move around.","Unknown contents near an open flame."]]},

{id:"SC-10",a:"VIII",t:"G",d:3,c:1,s:1,ref:"PTS VIII.G; BFH",
 q:"Scenario: You're in a light-wind approach and realize you'll pass about 30 feet over a power line at the field edge. Fuel is fine. Continue?",
 m:"No — 30 feet is too little margin given gusts, sink, and burner lag. Climb early to a comfortable altitude over the line, then pick a field past it, or abort to a different field. Never accept a marginal crossing of wires.",
 ans:[["B","No — 30 feet is too thin. Climb early with margin, or go to another field.","Correct risk judgment."],
 ["S","I'd add more height first — 30 feet over wires is too close for comfort.","Correct direction."],
 ["W","Yes — 30 feet clears the wires, and touching down right after them saves the field.","Margin too small for sink and lag."],
 ["W","Yes, if the crew stands by to warn me, since they can see the wire height from the ground.","Doesn't create margin."]]}
];
if (typeof module !== "undefined") module.exports = {BANK2};
